9	// Spec pose-worktree-runtime-qos-and-measurement.
10	
11	// runtimeAdmission is the runtime's policy for hosted commands: two lanes, each with its own
12	// slots and queue, so that a short query is never queued behind a heavy check, and a bound on
13	// what waits. The defaults are the ones the measurements of the spec were made with.
14	type runtimeAdmission struct {
15		HeavySlots, ShortSlots int
16		HeavyQueue, ShortQueue int
17		MemoMiB                int
18	}
19	
20	func defaultRuntimeAdmission() runtimeAdmission {
21		heavy := 1
22		short := 2
23		if runtime.GOMAXPROCS(0) < 2 {
24			short = 1
25		}
26		return runtimeAdmission{HeavySlots: heavy, ShortSlots: short, HeavyQueue: 4, ShortQueue: 16, MemoMiB: 256}
27	}
28	
29	// shortCommands are the hosted commands that answer in well under a second on a repository of
30	// this size (measured in the spec: surface-check of one spec takes about 10 ms; roadmap-check
31	// takes minutes here); every other hosted command is heavy.
32	var shortCommands = map[string]bool{"surface-check": true}
33	
34	// hostedLane is one lane of the admission policy and its counters.
35	type hostedLane struct {
36		name     string
37		slots    chan struct{}
38		maxQueue int64
39		queued   atomic.Int64
40		running  atomic.Int64
41		admitted atomic.Int64
42		refused  atomic.Int64
43		waitNS   atomic.Int64
44		maxWait  atomic.Int64
45	}
46	
47	func newHostedLane(name string, slots, queue int) *hostedLane {
48		if slots < 1 {
49			slots = 1
50		}
51		return &hostedLane{name: name, slots: make(chan struct{}, slots), maxQueue: int64(queue)}
52	}
53	
54	// enter reserves a place in the queue; false means every slot is busy and the queue is full,
55	// and the command is refused before it waits. Two arrivals that find the same last free slot
56	// may both wait: the queue limit can be exceeded by the arrivals of one instant.
57	func (l *hostedLane) enter() bool {
58		if l.queued.Add(1) > l.maxQueue && len(l.slots) == cap(l.slots) {
59			l.queued.Add(-1)
60			l.refused.Add(1)
61			return false
62		}
63		return true
64	}
65	
66	func (l *hostedLane) admit(wait time.Duration) {
67		l.queued.Add(-1)
68		l.running.Add(1)
69		l.admitted.Add(1)
70		l.waitNS.Add(int64(wait))
71		for {
72			cur := l.maxWait.Load()
73			if int64(wait) <= cur || l.maxWait.CompareAndSwap(cur, int64(wait)) {
74				return
75			}
76		}
77	}
78	
79	func (l *hostedLane) withdrawn() { l.queued.Add(-1); l.refused.Add(1) }
80	
81	func (l *hostedLane) metrics(out map[string]int64) {
82		out[l.name+"_slots"] = int64(cap(l.slots))
83		out[l.name+"_queue_limit"] = l.maxQueue
84		out[l.name+"_queued"] = l.queued.Load()
85		out[l.name+"_running"] = l.running.Load()
86		out[l.name+"_admitted"] = l.admitted.Load()
87		out[l.name+"_refused"] = l.refused.Load()
88		out[l.name+"_wait_ms_total"] = l.waitNS.Load() / int64(time.Millisecond)
89		out[l.name+"_wait_ms_max"] = l.maxWait.Load() / int64(time.Millisecond)
90	}
91	
92	type hostedLanes struct{ heavy, short *hostedLane }
93	
94	func newHostedLanes(p runtimeAdmission) *hostedLanes {
95		return &hostedLanes{heavy: newHostedLane("heavy", p.HeavySlots, p.HeavyQueue), short: newHostedLane("short", p.ShortSlots, p.ShortQueue)}
96	}
97	
98	func (h *hostedLanes) of(command string) *hostedLane {
99		if shortCommands[command] {
100			return h.short
101		}
102		return h.heavy
103	}
104	
105	func (h *hostedLanes) metrics() map[string]int64 {
106		out := map[string]int64{}
107		h.heavy.metrics(out)
108		h.short.metrics(out)
109		return out
110	}
